-- Read-only post-check for 20270102080000_editions_hardening.sql. Every row should say ok = true.
select 'anon cannot read internal organiser columns' as check, count(*) = 0 as ok from information_schema.column_privileges where table_schema = 'public' and table_name = 'edition_organisers' and grantee = 'anon' and privilege_type = 'SELECT' and column_name in ('verification_note','verified_by','created_by','reserved_name_flag','contact_email');
select 'authenticated cannot read verification note, verifier, creator or reserved flag' as check, count(*) = 0 as ok from information_schema.column_privileges where table_schema = 'public' and table_name = 'edition_organisers' and grantee = 'authenticated' and privilege_type = 'SELECT' and column_name in ('verification_note','verified_by','created_by','reserved_name_flag');
select 'anon cannot read venue notes or update author ids' as check, count(*) = 0 as ok from information_schema.column_privileges where table_schema = 'public' and grantee = 'anon' and privilege_type = 'SELECT' and ((table_name = 'edition_venues' and column_name = 'notes') or (table_name = 'edition_updates' and column_name = 'created_by'));
select 'payer tables are not selectable by authenticated or anon' as check, count(*) = 0 as ok from information_schema.role_table_grants where table_schema = 'public' and table_name in ('edition_payments','edition_participations') and grantee in ('anon','authenticated') and privilege_type = 'SELECT';
select 'invite guard trigger present' as check, count(*) = 1 as ok from pg_trigger where tgname = 'aa_edition_links_invite_guard' and not tgisinternal;
select 'admin-only and account-deletion functions are not executable by anon or by ordinary users where they must not be' as check, count(*) = 0 as ok from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname in ('delete_member_editions','edition_links_invite_guard') and (has_function_privilege('anon', p.oid, 'execute') or has_function_privilege('authenticated', p.oid, 'execute'));
select 'admin functions refuse anon' as check, count(*) = 0 as ok from pg_proc p where p.pronamespace = 'public'::regnamespace and p.proname in ('admin_edition_org_internal','admin_edition_org_flags') and has_function_privilege('anon', p.oid, 'execute');
